<?php
namespace Modules\BankingMicrofinance\Http\Controllers;use Illuminate\Http\Request;use Modules\BankingMicrofinance\Entities\PenaltyRule;use Modules\BankingMicrofinance\Entities\InstallmentPenalty;
class PenaltyController extends Controller{public function rules(){$items=PenaltyRule::latest()->paginate(25);return view('bankingmicrofinance::penalties.rules',compact('items'));}public function storeRule(Request $request){PenaltyRule::create($request->all());return back()->with('status','Penalty rule saved.');}public function charges(){$items=InstallmentPenalty::latest()->paginate(25);return view('bankingmicrofinance::penalties.charges',compact('items'));}public function waive(Request $request,InstallmentPenalty $penalty){$penalty->update(['waived_amount'=>$request->waived_amount,'status'=>'waived','remarks'=>$request->remarks]);return back()->with('status','Penalty waived.');}}
